public List<int> LeadersBruteForce(int[] arr)
{
    var leaders = new List<int>();
    int n = arr.Length;
    for (int i = 0; i < n; i++)
    {
        bool isLeader = true;
        for (int j = i + 1; j < n; j++)
        {
            if (arr[i] < arr[j])
            {
                isLeader = false;
                break;
            }
        }
        if (isLeader)
            leaders.Add(arr[i]);
    }
    return leaders;
}

public List<int> Leaders(int[] arr)
{
    var leaders = new List<int>();
    if (arr.Length == 0) return leaders;
    int maxFromRight = arr[arr.Length - 1];
    leaders.Add(maxFromRight);
    for (int i = arr.Length - 2; i >= 0; i--)
    {
        if (arr[i] > maxFromRight)
        {
            maxFromRight = arr[i];
            leaders.Add(maxFromRight);
        }
    }
    leaders.Reverse();
    return leaders;
}
